const body = $json.body || $json;

function sanitizeForTTS(text) {
  if (!text) return '';
  let clean = text.replace(/n[#º]\s*(\d+)/gi, 'número $1');
  clean = clean.replace(/n[#º]/gi, 'número');
  clean = clean.replace(/#/g, ' número ');
  clean = clean.replace(/&/g, ' e ');
  clean = clean.replace(/\+/g, ' mais ');
  clean = clean.replace(/%/g, ' por cento ');
  clean = clean.replace(/@/g, ' arroba ');
  clean = clean.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  clean = clean.replace(/[^a-zA-Z0-9\s.,!?:\-]/g, ' ');
  return clean.replace(/\s+/g, ' ').trim();
}

const itemReparadoSanitizado = sanitizeForTTS(body.item_reparado);
const clienteNomeSanitizado = sanitizeForTTS(body.cliente?.nome || 'Cliente');

const rawAudio = `Olá, ${clienteNomeSanitizado}! Aqui é da Sapataria Souza. Passando para avisar que o seu ${itemReparadoSanitizado || 'aparelho'} já está pronto e você pode vir buscá-lo.`;

const audio1 = sanitizeForTTS(rawAudio);

return {
  external_call_id: body.external_call_id,
  ordem_servico_id: body.ordem_servico_id,
  cliente_nome: clienteNomeSanitizado,
  cliente_telefone: body.cliente?.telefone ? body.cliente.telefone.replace(/^\+55/, '').replace(/^\+/, '') : '',
  item_reparado: itemReparadoSanitizado,
  callback_url: body.callback_url,
  audio1: audio1
};
